<?php
declare(strict_types=1);
require_once __DIR__.'/StaySchema.php';
final class Refunds
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function text(mixed $v,int $min,int $max):string{if(!is_string($v)||str_contains($v,"\0"))throw new HttpError(400,'Thông tin hoàn tiền không hợp lệ.');$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);$n=$v===null?-1:strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2;if($n<$min||$n>$max)throw new HttpError(400,'Kiểm tra độ dài thông tin hoàn tiền.');return $v;}
    private static function code(mixed $v):string{$v=mb_strtoupper(self::text($v,1,80),'UTF-8');if(!preg_match('/^(?:J[MGCBH][A-F0-9]{10}|JM-[XG][A-F0-9]{12})$/D',$v))throw new HttpError(400,'Mã đơn không hợp lệ.');return $v;}
    private static function uuid(mixed $v):string{if(!is_string($v)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$v))throw new HttpError(400,'Mã yêu cầu không hợp lệ.');return strtolower($v);}
    private static function integer(mixed $v):int{if(!is_int($v)||$v<1||$v>15000000000)throw new HttpError(400,'Khoản hoàn từ 1 đến 15 tỷ đồng.');return $v;}
    private static function safe(mixed $v):int{if(!is_numeric($v)||$v<0||$v>9007199254740991||floor((float)$v)!=(float)$v)throw new HttpError(409,'Sổ tiền không hợp lệ. Cần đối chiếu dữ liệu.');return (int)$v;}
    private function tx(callable $fn):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$r=$fn();$this->db->commit();return $r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    private function table(string $name):bool{return $this->query('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',[$name])->fetchColumn()!==false;}
    private function rootGuard(string $kind,string $id):void
    {
        if($kind==='ORDER'&&$this->table('jingo_cart_orders')&&$this->table('jingo_carts')){$cart=$this->query('SELECT c.code FROM jingo_cart_orders m JOIN jingo_carts c ON c.id=m.cart_id WHERE m.order_id=?',[$id])->fetchColumn();if($cart!==false)throw new HttpError(409,'Đơn thuộc giỏ '.$cart.'. Tra cứu và ghi hoàn theo mã giỏ tổng.');}
        if(in_array($kind,['GIFT','RIDE','CART'],true)&&$this->table('jingo_checkout_members')&&$this->table('jingo_checkout_bundles')){$bundle=$this->query("SELECT b.code FROM jingo_checkout_members m JOIN jingo_checkout_bundles b ON b.id=m.bundle_id WHERE m.kind=? AND m.entity_id=?",[$kind==='RIDE'?'rideId':($kind==='CART'?'cartId':'giftId'),$id])->fetchColumn();if($bundle!==false)throw new HttpError(409,'Đơn thuộc thanh toán chung '.$bundle.'. Ghi hoàn theo mã JB để tránh hoàn trùng.');}
    }
    private function target(string $code,bool $lock=true,bool $transfer=false):array
    {
        $payeeType='CUSTOMER';
        if(str_starts_with($code,'JH')){
            $row=$this->query('SELECT id,data FROM jingo_stay_bookings WHERE code=?'.($lock?' FOR UPDATE':''),[$code])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy đơn phòng.');$kind='HOTEL';$d=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$payer=$d['contact']['name'];$phone=$d['contact']['phone'];$paid=self::safe($this->query("SELECT COALESCE(SUM(amount),0) FROM jingo_payment_references WHERE entity_id=? AND kind='HOTEL_PAYMENT'",[$row['id']])->fetchColumn());
        }elseif(str_starts_with($code,'JM-G')){
            $row=$this->query('SELECT id,data FROM jingo_gift_orders WHERE code=?'.($lock?' FOR UPDATE':''),[$code])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy đơn quà.');$kind='GIFT';$this->rootGuard($kind,$row['id']);$d=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$payer=$d['name'];$phone=$d['phone'];$paid=($d['paymentStatus']??'UNPAID')==='PAID'?self::safe($d['paidAmount']??0):0;
        }elseif(str_starts_with($code,'JM-X')){
            $row=$this->query('SELECT id,data FROM jingo_ride_bookings WHERE code=?'.($lock?' FOR UPDATE':''),[$code])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy đơn xe.');$kind='RIDE';$this->rootGuard($kind,$row['id']);$d=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$payer=$d['contact']['name']??'';$phone=$d['contact']['phone']??'';$paid=($d['paymentStatus']??'UNPAID')==='PAID'?self::safe($d['paidAmount']??0):0;if($paid>0&&str_starts_with($d['paymentReference']??'','SEPAY:LIVE:')){$ledger=$this->query("SELECT amount FROM jingo_payment_references WHERE kind='RIDE_PAYMENT' AND entity_id=? AND reference_hash=?",[$row['id'],hash('sha256',$d['paymentReference'])])->fetchColumn();if($ledger===false||self::safe($ledger)!==$paid)throw new HttpError(409,'Khoản thu xe không khớp sổ gốc.');}
        }elseif(str_starts_with($code,'JC')){
            $row=$this->query('SELECT id,partner_id FROM jingo_carts WHERE code=?'.($lock?' FOR UPDATE':''),[$code])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy giỏ vé.');$kind='CART';$this->rootGuard($kind,$row['id']);$members=$this->query('SELECT o.id,o.contact FROM jingo_cart_orders m JOIN jingo_orders o ON o.id=m.order_id WHERE m.cart_id=? ORDER BY o.id'.($lock?' FOR UPDATE':''),[$row['id']])->fetchAll(PDO::FETCH_ASSOC);if(!$members)throw new HttpError(409,'Giỏ thiếu đơn con.');$d=json_decode($members[0]['contact'],true,512,JSON_THROW_ON_ERROR);$payer=$d['name'];$phone=$d['phone'];$paid=0;foreach($members as $m)$paid=self::safe($paid+self::safe($this->query('SELECT COALESCE(SUM(amount),0) FROM jingo_order_payments WHERE order_id=?',[$m['id']])->fetchColumn()));if($row['partner_id']!==null){$raw=$this->query('SELECT data FROM jingo_partners WHERE id=?',[$row['partner_id']])->fetchColumn();if($raw===false)throw new HttpError(409,'Cần đối chiếu thông tin CTV trước khi ghi hoàn.');$d=json_decode($raw,true,512,JSON_THROW_ON_ERROR);$payer=$d['name'];$phone=$d['phone']??'';$payeeType='PARTNER';}
        }elseif(str_starts_with($code,'JB')){$row=$this->query('SELECT * FROM jingo_checkout_bundles WHERE code=?'.($lock?' FOR UPDATE':''),[$code])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy đơn thanh toán chung.');$kind='BUNDLE';if(!$transfer&&!empty($row['lookup_pending']))throw new HttpError(409,'Mã tổng cũ chưa hoàn tất đối soát chuyển dữ liệu.');$d=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$payer=$d['contact']['name']??'';$phone=$d['contact']['phone']??'';$paid=$row['status']==='PAID'?self::safe($this->query("SELECT COALESCE(SUM(amount),0) FROM jingo_payment_references WHERE entity_id=? AND kind='BUNDLE_PAYMENT'",[$row['id']])->fetchColumn()):0;
        }else{
            $row=$this->query('SELECT id,contact FROM jingo_orders WHERE code=?'.($lock?' FOR UPDATE':''),[$code])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy đơn vé.');$kind='ORDER';$this->rootGuard($kind,$row['id']);$d=json_decode($row['contact'],true,512,JSON_THROW_ON_ERROR);$payer=$d['name'];$phone=$d['phone'];$paid=self::safe($this->query('SELECT COALESCE(SUM(amount),0) FROM jingo_order_payments WHERE order_id=?',[$row['id']])->fetchColumn());$partner=$this->query('SELECT p.data FROM jingo_partner_orders o JOIN jingo_partners p ON p.id=o.partner_id WHERE o.order_id=?',[$row['id']])->fetchColumn();if($partner!==false){$d=json_decode($partner,true,512,JSON_THROW_ON_ERROR);$payer=$d['name'];$phone=$d['phone']??'';$payeeType='PARTNER';}
        }
        if($paid<=0)throw new HttpError(409,'Đơn chưa có khoản thực thu. Công nợ chưa thu không phải tiền đã nhận.');$refunded=self::safe($this->query('SELECT COALESCE(SUM(amount),0) FROM jingo_refunds WHERE root_kind=? AND root_id=?',[$kind,$row['id']])->fetchColumn());if($refunded>$paid)throw new HttpError(409,'Sổ hoàn vượt thực thu. Cần đối chiếu dữ liệu.');return ['kind'=>$kind,'id'=>$row['id'],'code'=>$code,'paid'=>$paid,'payer'=>$payer,'phone'=>$phone,'payeeType'=>$payeeType,'refunded'=>$refunded,'remaining'=>$paid-$refunded];
    }
    public function transferState(string $code,bool $lock):array
    {
        if(!$this->db->inTransaction())throw new LogicException('Transfer state requires transaction.');
        // Runtime readers assume validated snapshots. A partial imported parent must fail closed.
        set_error_handler(static function(int $severity,string $message):never{throw new ErrorException('Invalid runtime parent snapshot.',0,$severity);});
        try{return $this->target(self::code($code),$lock,true);}finally{restore_error_handler();}
    }
    public function preview(array $in):array{if(count($in)!==1)throw new HttpError(400,'Yêu cầu tra cứu không hợp lệ.');$code=self::code($in['code']??null);return $this->tx(fn()=>$this->target($code));}
    public function create(array $in,string $actor):array
    {
        if(array_diff(array_keys($in),['code','requestId','amount','recipient','method','reference','refundedOn','note','verified'])||!in_array($in['method']??null,['BANK','CASH','GATEWAY'],true)||($in['verified']??null)!==true)throw new HttpError(400,'Kiểm tra hình thức và xác nhận đã hoàn tiền.');
        $v=['code'=>self::code($in['code']??null),'requestId'=>self::uuid($in['requestId']??null),'amount'=>self::integer($in['amount']??null),'recipient'=>self::text($in['recipient']??null,2,150),'method'=>$in['method'],'reference'=>self::text(array_key_exists('reference',$in)?$in['reference']:'',0,150),'refundedOn'=>StaySchema::date($in['refundedOn']??null),'note'=>self::text($in['note']??null,5,1000),'verified'=>true];
        if($v['refundedOn']>(new DateTimeImmutable('now',new DateTimeZone('Asia/Ho_Chi_Minh')))->format('Y-m-d'))throw new HttpError(400,'Ngày hoàn tiền không được ở tương lai.');if($v['method']!=='CASH'&&strlen(mb_convert_encoding($v['reference'],'UTF-16LE','UTF-8'))/2<3)throw new HttpError(400,'Nhập mã giao dịch hoàn tiền.');
        $hash=hash('sha256',json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_LINE_TERMINATORS|JSON_THROW_ON_ERROR));$ref=$v['method']==='CASH'?'CASH:'.$v['requestId']:mb_strtoupper($v['reference'],'UTF-8');$key=$v['method'].':'.$ref;
        try{return $this->tx(function()use($v,$hash,$ref,$key,$actor){$prior=$this->query('SELECT data FROM jingo_refunds WHERE id=?',[$v['requestId']])->fetchColumn();if($prior!==false){if(!hash_equals(json_decode($prior,true,512,JSON_THROW_ON_ERROR)['fingerprint'],$hash))throw new HttpError(409,'Mã yêu cầu đã dùng với nội dung khác.');return ['id'=>$v['requestId'],'recorded'=>true];}$target=$this->target($v['code']);if($v['amount']>$target['remaining'])throw new HttpError(409,'Khoản hoàn vượt số còn có thể hoàn: '.number_format($target['remaining'],0,',','.').' đ.');$data=['recipient'=>$v['recipient'],'method'=>$v['method'],'reference'=>$ref,'note'=>$v['note'],'payer'=>$target['payer'],'payeeType'=>$target['payeeType'],'actor'=>$actor,'fingerprint'=>$hash];$this->query('INSERT INTO jingo_refunds(id,root_kind,root_id,root_code,amount,refunded_on,reference_key,data) VALUES (?,?,?,?,?,?,?,?)',[$v['requestId'],$target['kind'],$target['id'],$target['code'],$v['amount'],$v['refundedOn'],$key,json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'payment.refund.record',$v['requestId']]);return ['id'=>$v['requestId'],'recorded'=>true];});}catch(PDOException $e){if(($e->errorInfo[1]??0)===1062)throw new HttpError(409,'Mã giao dịch hoàn tiền đã được ghi nhận.');throw $e;}
    }
    public function list(array $in):array
    {
        if(array_diff(array_keys($in),['q','page'])||array_key_exists('q',$in)&&!is_string($in['q'])||array_key_exists('page',$in)&&(!is_int($in['page'])&&!is_string($in['page'])||!preg_match('/^[1-9][0-9]{0,5}$/D',(string)$in['page'])||(int)$in['page']>100000))throw new HttpError(400,'Bộ lọc hoàn tiền không hợp lệ.');$q=self::text($in['q']??'',0,120);
        return $this->tx(function()use($in,$q){$args=[];$where='';if($q!==''){$where=" WHERE (root_code LIKE ? OR JSON_UNQUOTE(JSON_EXTRACT(data,'$.recipient')) LIKE ? OR JSON_UNQUOTE(JSON_EXTRACT(data,'$.reference')) LIKE ?)";$needle='%'.str_replace(['\\','%','_'],'',$q).'%';$args=[$needle,$needle,$needle];}$total=(int)$this->query('SELECT COUNT(*) FROM jingo_refunds'.$where,$args)->fetchColumn();$page=min((int)($in['page']??1),max(1,(int)ceil($total/25)));$rows=$this->query('SELECT id,root_code,root_kind,amount,refunded_on,data,created_at FROM jingo_refunds'.$where.' ORDER BY created_at DESC,id DESC LIMIT 25 OFFSET '.(($page-1)*25),$args)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);$r['amount']=(int)$r['amount'];$r['data']=array_intersect_key($d,array_flip(['recipient','payer','payeeType','method','reference','note','actor']));$r['data']['actorName']=$this->query('SELECT email FROM jingo_admins WHERE id=?',[$d['actor']])->fetchColumn()?:$d['actor'];}unset($r);return ['data'=>$rows,'total'=>$total,'page'=>$page,'pageSize'=>25];});
    }
}
